pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;

    function setUp() public { c = new airPort(); }

    function testFuzz_property(uint256 n, address from, uint256 v) public {
        n = bound(n, 2, 20);
        address[] memory tos = new address[](n);
        for (uint256 i = 0; i < n; i++) {
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(uint160(i))))));
        }

        Recorder rec = new Recorder();

        bool ok = false;
        try c.transfer(from, address(rec), tos, v) {
            ok = true;
        } catch {}

        assertTrue(ok && rec.calls() == n);
    }
}

contract Recorder {
    uint256 public calls;

    function transferFrom(address, address, uint256) external returns (bool) {
        calls++;
        return true;
    }

    receive() external payable {}
}
